-- New in the library
INSERT INTO result_fields (id, "order", type, unit, iso2_code, category, comments, source, commodity_metadata, analysis_metadata, created_by) VALUES
    ('nCI_Forest_bnetd_2020', 2205, 'numeric', 'ha / %', 'CI', 'Tree cover datasets', 'Forest for 2020 following the FAO definition, i.e., forest land classes 1-7 (dense, open, gallery, secondary/degraded, mangrove, forest plantation/reforestation and swamp forest, each above 30% tree cover as in the national forest definition) plus tree savannah (class 16, trees 5-20 m at 10-30% cover). BNETD note that forest land and wooded savannah together encompass the FAO definition, and the JRC comparison with GFC2020 uses the same classes (Verhegghen et al., 2024, Annex 2). In the independent validation (March 2024) the forest classes reached 81% user''s and producer''s accuracy, tree savannah 45%. Minimum mapping unit 0.5 ha. For Côte d''Ivoire only.', 'BNETD-CIGN (2024). Occupation des sols de la Côte d''Ivoire en 2020 . Centre d''Information Géographique et du Numérique / Bureau National d''Études Techniques et de Developpement, Côte d''Ivoire, with support from the European Union. Data available online from: https://developers.google.com/earth-engine/datasets/catalog/BNETD_land_cover_v1. Methodology (French): https://africageoportal.maps.arcgis.com/sharing/rest/content/items/76dc18767b89472eb89e8aa54e08a6c9/data. Forest definition and validation: https://africageoportal.maps.arcgis.com/sharing/rest/content/items/26a717d4c13f4f3db2c6056f7e5c0bab/data. Verhegghen, A., et al. (2024). Use of national versus global land use maps to assess deforestation risk in the context of the EU Regulation on Deforestation-free products: case study from Côte d''Ivoire . JRC138965, Publications Office of the European Union. https://doi.org/10.2760/7042220. Validation: CLS and TerraSphere (2024). COPERNICUS4GEOGLAM Validation Note Land Cover V2 Côte d''Ivoire . https://africageoportal.maps.arcgis.com/sharing/rest/content/items/0072843eefe545b1b43b0c5b2ebec41a/data', '{"pcrop":{"dataTheme":"treecover","usedForRisk":true},"acrop":{"dataTheme":"treecover","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"nci_bnetd_forest_2020_prep","geeAssets":["ee.Image(\"BNETD/land_cover/v1/2020\")"]}'::jsonb, 'migration')
ON CONFLICT (id) DO NOTHING;

