UPDATE result_fields SET comments = 'True when more than half of the plot is in permanent water (for a point, when the point falls on water), as a sign the plot may be in the wrong place. It does not change the risk outcome. JRC''s Global Surface Water data for inland water bodies (classes 1, 2, or 7 from the transitions layer); areas outside USGS Global Shoreline Vector (GSV) boundaries for marine; combined in the asset projects/ee-andyarnellgee/assets/water_mask_jrc_usgs.', updated_by = 'migration' WHERE id = 'In_waterbody';
UPDATE result_fields SET comments = 'Palm probability model (model_2026a). Filtered collection to 2020 data. Presence where probability is above 0.47: the threshold where precision and recall are equal (~89%) on the FDaP model selection set (model_2026a README, Technical validation, Table 6). Shown in the output but not yet used in the risk decision trees.', source = 'FDaP (2026). Forest Data Partnership https://developers.google.com/earth-engine/datasets/publisher/forestdatapartnership. Model notes and thresholds: https://github.com/google/forest-data-partnership/tree/main/models/model_2026a', analysis_metadata = analysis_metadata || '{"geeAssets":["ee.ImageCollection(\"projects/forestdatapartnership/assets/palm/model_2026a\")"]}'::jsonb, updated_by = 'migration' WHERE id = 'Oil_palm_FDaP';
